import openpyxl

wb = openpyxl.load_workbook('protein_expression.xlsx')
task = wb['Task']

print("=== TASK SHEET - Statistics section (rows 22-28) ===")
for row in range(22, 29):
    row_vals = []
    for col in range(1, 13):
        val = task.cell(row=row, column=col).value
        if val is not None:
            row_vals.append(f"{openpyxl.utils.get_column_letter(col)}{row}:{val}")
    if row_vals:
        print(f"Row {row}: {row_vals}")

print("\n=== TASK SHEET - Fold change section (rows 30-42) ===")
for row in range(30, 43):
    row_vals = []
    for col in range(1, 6):
        val = task.cell(row=row, column=col).value
        if val is not None:
            row_vals.append(f"{openpyxl.utils.get_column_letter(col)}{row}:{val}")
    if row_vals:
        print(f"Row {row}: {row_vals}")

# Check column B for rows 11-20 (Gene_Symbol)
